#!/usr/bin/env python3
"""Run /workspace/executable with given args. Usage:
  r.py [--stdin-file F | --stdin-str S | --stdin-closed | --stdin-devnull] [--env K=V ...] -- ARGS...
Prints repr of stdout, stderr, exit code.
"""
import os, sys, subprocess

args = sys.argv[1:]
stdin_mode = ('devnull', None)
env = dict(os.environ)
out = []
while args:
    a = args[0]
    if a == '--stdin-file':
        stdin_mode = ('file', args[1]); args = args[2:]
    elif a == '--stdin-str':
        stdin_mode = ('str', args[1]); args = args[2:]
    elif a == '--stdin-closed':
        stdin_mode = ('closed', None); args = args[1:]
    elif a == '--stdin-devnull':
        stdin_mode = ('devnull', None); args = args[1:]
    elif a == '--stdin-tty':
        stdin_mode = ('tty', None); args = args[1:]
    elif a == '--env':
        k, _, v = args[1].partition('='); env[k] = v; args = args[2:]
    elif a == '--unsetenv':
        env.pop(args[1], None); args = args[2:]
    elif a == '--':
        args = args[1:]; break
    else:
        break

cmd = ['/workspace/executable'] + args

kw = {}
extra_close = None
if stdin_mode[0] == 'file':
    kw['stdin'] = open(stdin_mode[1], 'rb')
elif stdin_mode[0] == 'str':
    kw['stdin'] = subprocess.PIPE
elif stdin_mode[0] == 'closed':
    kw['stdin'] = None  # handled via preexec
elif stdin_mode[0] == 'devnull':
    kw['stdin'] = subprocess.DEVNULL
elif stdin_mode[0] == 'tty':
    import pty
    m, s = pty.openpty()
    kw['stdin'] = s

if stdin_mode[0] == 'closed':
    def pf():
        os.close(0)
    kw['preexec_fn'] = pf
    kw['stdin'] = subprocess.DEVNULL

p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env, **kw)
if stdin_mode[0] == 'str':
    o, e = p.communicate(stdin_mode[1].encode())
else:
    o, e = p.communicate()
print("STDOUT: " + repr(o))
print("STDERR: " + repr(e))
print("exit=%d" % p.returncode)

