#!/usr/bin/env python3
"""pty-stdout runner with full env control.
Usage: pr.py [--env K=V]... [--unsetenv K]... [--stdin-str S] [--pty-stdin] -- ARGS...
"""
import os, pty, sys, subprocess

args = sys.argv[1:]
env = dict(os.environ)
stdin_data = None
pty_stdin = False
while args:
    a = args[0]
    if a == '--env':
        k, _, v = args[1].partition('='); env[k] = v; args = args[2:]
    elif a == '--unsetenv':
        env.pop(args[1], None); args = args[2:]
    elif a == '--stdin-str':
        stdin_data = args[1].encode(); args = args[2:]
    elif a == '--pty-stdin':
        pty_stdin = True; args = args[1:]
    elif a == '--':
        args = args[1:]; break
    else:
        break

cmd = ['/workspace/executable'] + args
m, s = pty.openpty()
kw = {}
if pty_stdin:
    im, isl = pty.openpty()
    kw['stdin'] = isl
elif stdin_data is not None:
    kw['stdin'] = subprocess.PIPE
else:
    kw['stdin'] = subprocess.DEVNULL

p = subprocess.Popen(cmd, stdout=s, stderr=subprocess.PIPE, env=env, **kw)
os.close(s)
if pty_stdin:
    os.close(isl)
elif stdin_data is not None:
    try:
        p.stdin.write(stdin_data)
    except BrokenPipeError:
        pass
    p.stdin.close()

out = b""
import threading
err = [b""]
def rd():
    err[0] = p.stderr.read()
th = threading.Thread(target=rd); th.start()
try:
    while True:
        try:
            d = os.read(m, 65536)
        except OSError:
            break
        if not d: break
        out += d
except KeyboardInterrupt:
    pass
p.wait(); th.join()
os.close(m)
print("STDOUT: " + repr(out))
print("STDERR: " + repr(err[0]))
print("exit=%d" % p.returncode)

